//! DTOs generated by the pinned real production service; no Store imitation.
use notes_mcp::schema;
use serde_json::{Value, json};

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/document-boundary.json")).unwrap()
}

#[test]
fn real_service_create_update_read_accept_max_nodes_and_depth() {
    let fixture = fixture();
    let cases = fixture["cases"].as_array().unwrap();
    assert_eq!(cases.len(), 6);
    let definitions = schema::definitions();
    for case in cases {
        let name = case["tool"].as_str().unwrap();
        let definition = definitions.iter().find(|d| d.tool.name == name).unwrap();
        assert!(definition.input.is_valid(&case["arguments"]), "{name}");
        assert!(definition.output.is_valid(&case["result"]), "{name}");
        let content = if name == "notes_read" {
            assert_eq!(case["result"]["truncated"], false);
            &case["result"]["content"]
        } else {
            assert_eq!(case["result"]["committed"], true);
            &case["arguments"]["content"]
        };
        assert!(schema::bounded_content(content), "{name}");
    }
    let doc = &cases[0]["arguments"]["content"];
    assert_eq!(serde_json::to_vec(doc).unwrap().len(), 779_987);
    assert_eq!(doc["content"].as_array().unwrap().len(), 19_999);
    assert_eq!(cases[1]["arguments"]["content"], *doc);
    assert_eq!(cases[2]["result"]["content"], *doc);
    // Host capabilities continue advertising the unchanged public cap.
    let service: Value =
        serde_json::from_str(include_str!("fixtures/service-success.json")).unwrap();
    assert_eq!(service["cases"][0]["result"]["limits"]["maxNodes"], 20_000);
}

#[test]
fn resource_walk_matches_actual_native_depth_and_typed_object_count() {
    // These are native input_document resource checks, not full schema successes.
    for case in fixture()["resourceCases"].as_array().unwrap() {
        assert_eq!(
            schema::bounded_content(&case["content"]),
            case["accepted"].as_bool().unwrap()
        );
    }
}

#[test]
fn twenty_thousand_and_one_nodes_and_depth_sixty_five_stay_rejected() {
    let mut doc = fixture()["cases"][0]["arguments"]["content"].clone();
    doc["content"]
        .as_array_mut()
        .unwrap()
        .push(json!({"type":"heading", "attrs":{"level":1}}));
    assert!(!schema::bounded_content(&doc));
    let mut node = json!({"type":"paragraph"});
    for _ in 0..31 {
        node = json!({"type":"blockquote", "content":[node]});
    }
    assert!(!schema::bounded_content(
        &json!({"type":"doc", "content":[node]})
    ));
}
